/* Stand-in for the map page's jquery-ui-1.10.3.interact.min.js.
 *
 * init() makes every panel draggable/resizable/sortable. The userscript
 * replaces all three (automatic sizing owns the layout), so these only need to
 * exist for the chained .disableSelection() call.
 */
(function ($) {
    ['draggable', 'resizable', 'sortable'].forEach(function (name) {
        $.fn[name] = function () {
            return this;
        };
    });
    $.fn.disableSelection = function () {
        return this;
    };
})(jQuery);